'use strict';
(()=>{
 const online=['VNPAY','VNPAY_QR','VNPAY_CARD','SEPAY','SEPAY_CARD','PAYPAL'],isOnline=id=>online.includes(id),label=(id,en)=>({VNPAY:'VNPAY',VNPAY_QR:'VNPAY QR',VNPAY_CARD:en?'International card · VNPAY':'Thẻ quốc tế · VNPAY',SEPAY:en?'Bank transfer QR · SePay':'Chuyển khoản QR · SePay',SEPAY_CARD:en?'Card · SePay':'Thẻ · SePay',PAYPAL:'PayPal · USD'})[id]||id;
 window.jinmemoPaymentMethods={isOnline,label};
 window.bundlePaymentChoice=({parent,en=false})=>{
  const tr=(a,b)=>en?b:a,el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;},wrap=el('label',tr('Phương thức thanh toán','Payment method')),select=el('select'),status=el('p'),retry=el('button',tr('Tải lại phương thức','Reload payment methods'));select.name='paymentMethod';select.required=true;select.disabled=true;retry.type='button';wrap.append(select);parent.append(wrap,status,retry);let methods=[],wanted='',generation=0;
  function show(){const method=methods.find(m=>m.id===select.value);status.textContent=method?.instructions||tr('Chọn phương thức đang nhận. Thanh toán online chỉ ghi nhận sau khi cổng xác nhận.','Choose an available method. Online payment is recorded only after gateway confirmation.');}
  function apply(){select.replaceChildren();const blank=el('option',tr('Chọn phương thức…','Choose a payment method…'));blank.value='';select.append(blank);for(const m of methods){const option=el('option',m.name);option.value=m.id;select.append(option);}select.value=methods.some(m=>m.id===wanted)?wanted:'';select.disabled=!methods.length;show();if(!methods.length)status.textContent=tr('Chưa có phương thức thanh toán đang nhận. Liên hệ nhân viên trước khi đặt.','No payment methods are currently available. Contact our team before booking.');else if(wanted&&!methods.some(m=>m.id===wanted))status.textContent=tr('Phương thức đã chọn không còn nhận. Chọn lại để tiếp tục.','The previous method is unavailable. Choose another to continue.');}
  async function load(){const seq=++generation;methods=[];select.disabled=retry.disabled=true;status.textContent=tr('Đang tải phương thức…','Loading payment methods…');try{const response=await fetch('/api/v1/payments/options',{credentials:'omit',cache:'no-store'}),data=await response.json();if(!response.ok||!data||typeof data!=='object'||!Array.isArray(data.manualOptions)||!Array.isArray(data.providers)||!['LIVE','TEST'].includes(data.mode))throw Error(tr('Không tải được phương thức.','Unable to load payment methods.'));if(seq!==generation)return;const seen=new Set();for(const m of data.manualOptions){if(!m||typeof m.id!=='string'||!/^(CASH|PAY_LATER|MANUAL_[a-zA-Z0-9_-]{1,60})$/.test(m.id)||seen.has(m.id)||typeof m.name!=='string')throw Error(tr('Danh sách phương thức không hợp lệ.','Invalid payment methods.'));seen.add(m.id);methods.push({id:m.id,name:en?m.englishName||m.name:m.name,instructions:en?m.englishInstructions||m.instructions:m.instructions});}if(data.mode==='LIVE')for(const provider of data.providers){const id=provider==='VNPAY'?'VNPAY_QR':provider;if(isOnline(id)&&!seen.has(id)){seen.add(id);methods.push({id,name:label(id,en),instructions:tr('Sau khi đặt, mở bước thanh toán để tạo QR hoặc liên kết cổng. Chưa thu tiền tại bước xác nhận đơn.','After booking, open the payment step to create a QR or gateway link. Confirming the order does not collect payment.')});}}apply();}catch(error){if(seq===generation){methods=[];select.disabled=true;status.textContent=error.message;}}finally{if(seq===generation)retry.disabled=false;}}
  select.onchange=()=>{wanted=select.value;show();};retry.onclick=load;load();
  return {value(){if(select.disabled||!methods.some(m=>m.id===select.value))throw Error(tr('Chọn phương thức thanh toán đang nhận.','Choose an available payment method.'));return select.value;},restore(id){wanted=id||'';apply();}};
 };
})();
